try (var channel = new SubmissionPublisher<OrderPlaced>(executor, 256)) {
    channel.subscribe(new Flow.Subscriber<OrderPlaced>() {
        public void onSubscribe(Flow.Subscription s) { s.request(Long.MAX_VALUE); }
        public void onNext(OrderPlaced e) { billing.handle(e); }
        public void onError(Throwable t) { log.error("subscriber failed", t); }
        public void onComplete() { }
    });
    channel.submit(orderPlaced);   // one copy per current subscriber
}

